// frontend/src/pages/Home.js
import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';

const API_URL = 'http://localhost:3001/api';

function Home() {
    const [restaurants, setRestaurants] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        axios.get(`${API_URL}/restaurants`)
            .then(res => {
                setRestaurants(res.data);
                setLoading(false);
            })
            .catch(err => {
                console.error(err);
                setLoading(false);
            });
    }, []);

    if (loading) return <div className="main"><p>Загрузка...</p></div>;

    return (
        <div>
            <div className="hero">
                <h1>🍽️ OshMenu</h1>
                <p>Вся кухня Оша в одном месте. Заказывайте онлайн — забирайте в ресторане!</p>
            </div>

            <h2 style={{ marginBottom: '25px', fontSize: '28px' }}>Рестораны и кафе</h2>
            
            <div className="restaurants-grid">
                {restaurants.map(r => (
                    <Link to={`/restaurant/${r.id}`} key={r.id} className="restaurant-card">
                        <div className="restaurant-image">🍽️</div>
                        <div className="restaurant-info">
                            <h2>{r.name}</h2>
                            <p>{r.description}</p>
                            
                            <div className="restaurant-meta">
                                <span>📍 {r.address}</span>
                                <span className="rating">⭐ {r.rating}</span>
                            </div>
                            
                            <div className="categories-tags">
                                {r.categories.map((cat, idx) => (
                                    <span key={idx} className="category-tag">{cat}</span>
                                ))}
                            </div>
                        </div>
                    </Link>
                ))}
            </div>
        </div>
    );
}

export default Home;
